def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        raise ValueError("Cannot divide by zero")
    return x / y

def main():
    operations = {
        '+': add,
        '-': subtract,
        '*': multiply,
        '/': divide,
    }

    print("Basic Calculator")
    print("Operations: +, -, *, /")
    print("Type 'quit' to exit\n")

    while True:
        expr = input("Enter expression (e.g. 2 + 3): ").strip()
        if expr.lower() == 'quit':
            break

        parts = expr.split()
        if len(parts) != 3:
            print("Invalid input. Use format: number operator number\n")
            continue

        try:
            x = float(parts[0])
            op = parts[1]
            y = float(parts[2])
        except ValueError:
            print("Invalid numbers.\n")
            continue

        if op not in operations:
            print(f"Unknown operator '{op}'. Use +, -, *, /\n")
            continue

        try:
            result = operations[op](x, y)
            print(f"= {result}\n")
        except ValueError as e:
            print(f"Error: {e}\n")

if __name__ == '__main__':
    main()
